package pe.edu.utp.eventope.controller;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import pe.edu.utp.eventope.config.*;import pe.edu.utp.eventope.dto.*;import pe.edu.utp.eventope.service.ServicioCompra;import java.io.IOException;import java.sql.SQLException;
@WebServlet("/compras/confirmar")
public final class ConfirmarCompraServlet extends HttpServlet {
 private ServicioCompra servicio;public void init()throws ServletException{try{servicio=new ServicioCompra(new ConexionBD(Configuracion.cargar()));}catch(RuntimeException e){throw new ServletException("No se pudo configurar la compra",e);}}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{req.setCharacterEncoding("UTF-8");if(!pe.edu.utp.eventope.util.Csrf.valido(req.getSession(false),req.getParameter("csrf"))){resp.sendError(403,"Token de seguridad inválido");return;}Object a=req.getSession().getAttribute("sesionUsuario"),o=req.getSession().getAttribute("carritoCompra");if(!(a instanceof SesionUsuario actor)||actor.getTipo()!=SesionUsuario.Tipo.CLIENTE){resp.sendError(401);return;}if(!(o instanceof CarritoCompra c)||c.getNominaciones().size()!=c.getCantidadTotal()){req.getSession().setAttribute("errorCompra","Completa los datos de cada asistente antes de confirmar.");resp.sendRedirect(req.getContextPath()+"/compras/revision");return;}try{CompraConfirmada r=servicio.confirmar(actor.getId(),c);req.getSession().setAttribute("ultimaCompraId",r.getId());resp.sendRedirect(req.getContextPath()+"/compras/confirmacion?id="+r.getId());}catch(IllegalArgumentException|SQLException e){req.setAttribute("error",e.getMessage());req.setAttribute("carrito",c);req.setAttribute("csrf",pe.edu.utp.eventope.util.Csrf.token(req.getSession()));req.getRequestDispatcher("/WEB-INF/views/compras/revision.jsp").forward(req,resp);}}
}
